def die(msg: str, code: int = 1):
    print(f"\nABORT: {msg}")
    sys.exit(code)


def read(path: str) -> str:
    with open(path, encoding="utf-8") as f:
        return f.read()


# ───────────────────────────────────────────────── payloads
CARD_SRC    = '"""\nEXPIRY SUMMARY CARD — week + month P/L card sent at 15:40 on expiry days.\n\napp/api/telegram_expiry_card.py          ── EXPIRY_CARD_20260929 ──\n\nPURPOSE\n-------\nOne PNG per weekly expiry (NIFTY Tuesday, or the Monday before a Tuesday\nholiday): the expiry-cycle week and the trailing month, per book, per\nstrategy. Same Midnight palette, header and footer shape as the daily card\n(EOD_CARD_V2_20260929) so the two read as a set.\n\n  header   Expiry summary · weekday date time · "weekly expiry"\n  week     Live / Paper net for the 7 calendar days ending today (Wed→Tue,\n           the expiry cycle) + one cell per session, per book\n  month    Live / Paper net since the same calendar day last month + one\n           cell per expiry week, per book\n  table    per (strategy, book): week net·trades, month net·trades, month bar\n  footer   best / worst session of the week, positive sessions of the month\n           per book, month charges per book\n\nThe windows are the Modern dashboard\'s (fleet_today_routes._week_from /\n_month_from), so the card agrees with the ledger\'s Week P/L / Month P/L.\nLive and Paper are never summed.\n\nPure renderer: ExpiryCardData in, PNG bytes out. No DB here. Palette, pixel\nlayout constants and formatting helpers are imported from the daily card.\n\nFAIL-OPEN CONTRACT\n------------------\nbuild_expiry_card_png() returns PNG bytes or None on any failure; the sender\nthen falls back to a short text message so the summary is never lost.\n"""\n\nfrom __future__ import annotations\n\nimport io\nfrom dataclasses import dataclass, field\nfrom typing import Optional\n\nfrom app.api.telegram_summary_card import (   # ── EOD_CARD_V2_20260929 ── shared tokens\n    BG_CARD, TILE, BORDER, TXT_PRIMARY, TXT_MUTED, TXT_DIM, TXT_FAINT,\n    UP, DN, DOT_LIVE, DOT_PAPER, CURRENCY,\n    DPI, W_PX, PAD_L, PAD_R, PAD_TOP, PAD_BOT, HEADER_H, RULE_GAP, FOOTER_H,\n    FS_TITLE, FS_SUB, FS_CORNER, FS_LABEL, FS_NAME, FS_TAG, FS_TSUB, FS_CHART,\n    FS_FOOT_L, FS_FOOT_V, FS_FOOT_S,\n    _fmt_signed, _fmt_signed_rs, _hline,\n)\n\n# strip cell tints = TILE blended 16 % towards UP / DN\nCELL_UP   = "#263951"\nCELL_DN   = "#3f2544"\nCELL_ZERO = "#221d45"\n\nBOOKS = ("LIVE", "PAPER")\n\n\ndef _fmt_k(n: float) -> str:\n    """+18.2k / -8.2k / +655 — compact cell figure, explicit sign, half-up."""\n    from decimal import Decimal, ROUND_HALF_UP\n    n = float(n)\n    sign = "-" if n < 0 else "+"\n    a = Decimal(str(abs(n)))\n    if a >= 100_000:\n        return f"{sign}{(a / 1000).quantize(Decimal(\'1\'), ROUND_HALF_UP)}k"\n    if a >= 1000:\n        return f"{sign}{(a / 1000).quantize(Decimal(\'0.1\'), ROUND_HALF_UP)}k"\n    return f"{sign}{a.quantize(Decimal(\'1\'), ROUND_HALF_UP)}"\n\n\n# ════════════════════════════════════════════════════════════════════\n#  DATA MODEL\n# ════════════════════════════════════════════════════════════════════\n\n@dataclass\nclass Cell:\n    """One strip cell: a session (week strip) or an expiry week (month strip)."""\n    key: str                    # "2026-09-23" (session) / "2026-09-01" (expiry date)\n    label: str                  # "Wed" / "1 Sep"\n    net: Optional[float] = None # None = no closed trade in this cell\n    trades: int = 0\n\n\n@dataclass\nclass PeriodBook:\n    """One book (LIVE / PAPER) inside one period (week / month)."""\n    net: float = 0.0\n    trades: int = 0\n    wins: int = 0\n    charges: float = 0.0\n    approx: bool = False\n    cells: list = field(default_factory=list)   # [Cell] in time order\n    sessions: int = 0                           # sessions with ≥1 closed trade\n    positive_sessions: int = 0                  # of those, day net > 0\n\n    @property\n    def traded(self) -> bool:\n        return self.trades > 0\n\n    @property\n    def win_rate(self) -> float:\n        return (100.0 * self.wins / self.trades) if self.trades else 0.0\n\n\n@dataclass\nclass StrategyPeriodRow:\n    name: str\n    mode: str                   # "LIVE" | "PAPER"\n    week_net: float = 0.0\n    week_trades: int = 0\n    month_net: float = 0.0\n    month_trades: int = 0\n    approx: bool = False\n\n\n@dataclass\nclass ExpiryCardData:\n    date_str: str                               # "29 Sep 2026"\n    subtitle: str = ""                          # "Tue 29 Sep 2026 · 15:40 IST · weekly expiry"\n    week_range: str = ""                        # "Wed 23 – Tue 29 Sep · 5 sessions"\n    month_range: str = ""                       # "since Sat 29 Aug · by expiry week"\n    week: dict = field(default_factory=dict)    # book -> PeriodBook\n    month: dict = field(default_factory=dict)   # book -> PeriodBook\n    rows: list = field(default_factory=list)    # [StrategyPeriodRow], Live first, |month| desc\n    warnings: list = field(default_factory=list)\n\n    def book(self, period: str, book: str) -> PeriodBook:\n        d = self.week if period == "week" else self.month\n        return d.get(book) or PeriodBook()\n\n    @property\n    def any_trades(self) -> bool:\n        return any(self.book(p, b).traded for p in ("week", "month") for b in BOOKS)\n\n    def _week_cells_with_trades(self):\n        for b in BOOKS:\n            for c in self.book("week", b).cells:\n                if c.net is not None and c.trades:\n                    yield c, b\n\n    @property\n    def best_session(self):\n        cands = list(self._week_cells_with_trades())\n        return max(cands, key=lambda t: t[0].net) if cands else None\n\n    @property\n    def worst_session(self):\n        cands = list(self._week_cells_with_trades())\n        return min(cands, key=lambda t: t[0].net) if cands else None\n\n\n# ════════════════════════════════════════════════════════════════════\n#  RENDERER\n# ════════════════════════════════════════════════════════════════════\n\ndef build_expiry_card_png(data: ExpiryCardData) -> Optional[bytes]:\n    try:\n        return _render(data)\n    except Exception as e:  # noqa: BLE001 — fail-open is the contract\n        print(f"[EXPIRY_CARD] render failed, caller should fall back to text: {e}")\n        return None\n\n\nPANEL_H    = 172\nPANEL_GAP  = 12\nPANEL_LEFT = 300         # width of the numbers column inside a panel\nROW_H      = 30          # table row\nTABLE_HEAD = 26\nTABLE_GAP  = 22\nEMPTY_H    = 60\nFS_PANEL_V = 11          # panel Live / Paper value\nFS_CELL    = 6.8\n\n\ndef _render(data: ExpiryCardData) -> bytes:\n    import matplotlib\n    matplotlib.use("Agg")\n    import matplotlib.pyplot as plt\n    from matplotlib.patches import FancyBboxPatch, Rectangle\n\n    rows = list(data.rows)\n    table_h = (TABLE_HEAD + ROW_H * len(rows)) if rows else EMPTY_H\n\n    H_PX = (PAD_TOP + HEADER_H + 2 * PANEL_H + PANEL_GAP + TABLE_GAP + table_h\n            + RULE_GAP + FOOTER_H + PAD_BOT)\n\n    fig = plt.figure(figsize=(W_PX / DPI, H_PX / DPI), dpi=DPI)\n    fig.patch.set_facecolor(BG_CARD)\n    ax = fig.add_axes([0, 0, 1, 1])\n    ax.set_xlim(0, W_PX)\n    ax.set_ylim(H_PX, 0)\n    ax.axis("off")\n    renderer = fig.canvas.get_renderer()\n\n    def text(x, y, s, *, size=FS_NAME, color=TXT_PRIMARY, ha="left", va="top",\n             weight="normal", style="normal", zorder=6):\n        return ax.text(x, y, s, fontsize=size, color=color, ha=ha, va=va,\n                       weight=weight, style=style, zorder=zorder)\n\n    def text_w(artist) -> float:\n        return artist.get_window_extent(renderer).width\n\n    def rrect(x, y, w, h, *, fc=TILE, r=12, zorder=1):\n        ax.add_patch(FancyBboxPatch((x, y), w, h,\n                                    boxstyle=f"round,pad=0,rounding_size={r}",\n                                    facecolor=fc, edgecolor="none", zorder=zorder,\n                                    mutation_aspect=1))\n\n    def dot(x, y, color, s=40):\n        ax.scatter([x], [y], s=s, color=color, zorder=7, linewidths=0)\n\n    L, R = PAD_L, W_PX - PAD_R\n    y = PAD_TOP\n\n    # ── header ──────────────────────────────────────────────────────\n    text(L, y - 2, "Expiry summary", size=FS_TITLE, weight="medium")\n    text(L, y + 38, data.subtitle or data.date_str, size=FS_SUB, color=TXT_DIM)\n    text(R, y + 2,  "Scalp Terminal", size=FS_CORNER, color=TXT_FAINT, ha="right")\n    text(R, y + 24, "net of charges", size=FS_CORNER, color=TXT_FAINT, ha="right")\n    y += HEADER_H\n\n    # ── period panels ───────────────────────────────────────────────\n    def panel(py, title, rng, period):\n        rrect(L, py, R - L, PANEL_H)\n        x0 = L + 16\n        text(x0, py + 12, title, size=FS_LABEL, color=TXT_MUTED)\n        text(x0, py + 31, rng, size=FS_CHART, color=TXT_FAINT)\n        xr = L + PANEL_LEFT - 16          # right edge of the numbers column\n        yy = py + 64\n        for book, label, dc in (("LIVE", "Live", DOT_LIVE), ("PAPER", "Paper", DOT_PAPER)):\n            pb = data.book(period, book)\n            dot(x0 + 5, yy + 12, dc if pb.traded else TXT_FAINT, s=32)\n            text(x0 + 18, yy + 3, label, size=FS_TAG, color=TXT_MUTED if pb.traded else TXT_FAINT)\n            if pb.traded:\n                s = ("\\u2248 " if pb.approx else "") + _fmt_signed_rs(pb.net)\n                text(xr, yy - 4, s, size=FS_PANEL_V, color=UP if pb.net >= 0 else DN,\n                     ha="right", weight="bold")\n                sub = f"{pb.trades} trade{\'s\' if pb.trades != 1 else \'\'} \\u00b7 {pb.win_rate:.0f}% won"\n                text(xr, yy + 28, sub, size=FS_TSUB, color=TXT_DIM, ha="right")\n            else:\n                text(xr, yy + 3, "no trades", size=FS_TAG, color=TXT_FAINT, ha="right", style="italic")\n            yy += 52\n\n        # strips: label row + one row per book\n        sx0 = L + PANEL_LEFT + 16\n        sw  = R - 16 - sx0\n        lab_w = 58\n        cx0 = sx0 + lab_w\n        cw_total = sw - lab_w\n        cells_ref = data.book(period, "PAPER").cells or data.book(period, "LIVE").cells\n        n = max(1, len(cells_ref))\n        gap = 5\n        cw = (cw_total - gap * (n - 1)) / n\n        ly = py + 16\n        for i, c in enumerate(cells_ref):\n            text(cx0 + i * (cw + gap) + cw / 2, ly, c.label, size=FS_CHART,\n                 color=TXT_FAINT, ha="center")\n        ry = py + 44\n        for book, label in (("LIVE", "Live"), ("PAPER", "Paper")):\n            pb = data.book(period, book)\n            text(sx0, ry + 9, label, size=FS_CHART, color=TXT_FAINT)\n            cells = pb.cells if pb.cells else [Cell(c.key, c.label) for c in cells_ref]\n            for i, c in enumerate(cells[:n]):\n                cx = cx0 + i * (cw + gap)\n                if c.net is None or not c.trades:\n                    fc, col, s = CELL_ZERO, TXT_FAINT, "\\u2014"\n                else:\n                    fc = CELL_UP if c.net >= 0 else CELL_DN\n                    col = UP if c.net >= 0 else DN\n                    s = _fmt_k(c.net)\n                rrect(cx, ry, cw, 36, fc=fc, r=6, zorder=2)\n                text(cx + cw / 2, ry + 18, s, size=FS_CELL, color=col, ha="center",\n                     va="center", weight="bold" if c.trades else "normal")\n            ry += 50\n\n    panel(y, "This week", data.week_range, "week")\n    y += PANEL_H + PANEL_GAP\n    panel(y, "This month", data.month_range, "month")\n    y += PANEL_H + TABLE_GAP\n\n    # ── strategy table ──────────────────────────────────────────────\n    x_name = L\n    x_week = L + 372\n    x_month = L + 552\n    x_bar0, x_bar1 = L + 584, R\n    if not rows:\n        text((L + R) / 2, y + EMPTY_H / 2, "No closed trades in the month window",\n             size=FS_NAME, color=TXT_DIM, ha="center", va="center", style="italic")\n        y += EMPTY_H\n    else:\n        text(x_name, y, "Strategy", size=FS_CHART, color=TXT_FAINT)\n        text(x_week, y, "Week", size=FS_CHART, color=TXT_FAINT, ha="right")\n        text(x_month, y, "Month", size=FS_CHART, color=TXT_FAINT, ha="right")\n        _hline(ax, L, R, y + 20)\n        y += TABLE_HEAD\n        max_abs = max([abs(r.month_net) for r in rows] + [1.0])\n        half = (x_bar1 - x_bar0) / 2\n        xc = x_bar0 + half\n        for r in rows:\n            ty = y + 5\n            nx = x_name\n            is_live = r.mode == "LIVE"\n            if is_live:\n                dot(nx + 4, ty + 10, DOT_LIVE, s=26)\n                nx += 16\n            nm = text(nx, ty, r.name, size=FS_NAME)\n            text(nx + text_w(nm) + 6, ty + 3, "live" if is_live else "paper",\n                 size=FS_TAG, color=DOT_LIVE if is_live else TXT_DIM)\n\n            def numcell(xr, net, n, approx=False):\n                if not n:\n                    text(xr, ty, "\\u2014", size=FS_NAME, color=TXT_FAINT, ha="right")\n                    return\n                cnt = text(xr, ty + 4, str(n), size=FS_TSUB, color=TXT_DIM, ha="right")\n                s = ("\\u2248 " if approx else "") + _fmt_signed(net)\n                text(xr - text_w(cnt) - 6, ty, s, size=FS_NAME,\n                     color=UP if net >= 0 else DN, ha="right")\n\n            numcell(x_week, r.week_net, r.week_trades)\n            numcell(x_month, r.month_net, r.month_trades, r.approx)\n            # diverging bar on the month column (fleet-wide scale, 2 px floor)\n            ax.plot([xc, xc], [ty + 2, ty + 20], color=BORDER, linewidth=1, zorder=2)\n            if r.month_trades:\n                w = max(2.0, half * abs(r.month_net) / max_abs)\n                bx = xc if r.month_net >= 0 else xc - w\n                ax.add_patch(Rectangle((bx, ty + 7), w, 8, facecolor=UP if r.month_net >= 0 else DN,\n                                       edgecolor="none", zorder=3))\n            y += ROW_H\n\n    # ── footer ──────────────────────────────────────────────────────\n    y += RULE_GAP\n    _hline(ax, L, R, y)\n    y += RULE_GAP\n    cw4 = (R - L) / 4\n    for i, (label, value, vcolor, sub) in enumerate(_footer_cells(data)):\n        fx = L + i * cw4\n        text(fx, y, label, size=FS_FOOT_L, color=TXT_FAINT)\n        text(fx, y + 22, value, size=FS_FOOT_V, color=vcolor, weight="medium")\n        text(fx, y + 52, sub, size=FS_FOOT_S, color=TXT_DIM)\n\n    buf = io.BytesIO()\n    fig.savefig(buf, format="png", facecolor=BG_CARD, bbox_inches=None)\n    plt.close(fig)\n    buf.seek(0)\n    return buf.read()\n\n\ndef _footer_cells(data: ExpiryCardData):\n    b = data.best_session\n    w = data.worst_session\n    bk = lambda book: "L" if book == "LIVE" else "P"  # noqa: E731\n    c1 = (("Best session", _fmt_signed_rs(b[0].net), UP if b[0].net >= 0 else DN,\n           f"{b[0].label} \\u00b7 {\'Live\' if b[1] == \'LIVE\' else \'Paper\'} \\u00b7 week") if b\n          else ("Best session", "\\u2014", TXT_DIM, ""))\n    c2 = (("Worst session", _fmt_signed_rs(w[0].net), UP if w[0].net >= 0 else DN,\n           f"{w[0].label} \\u00b7 {\'Live\' if w[1] == \'LIVE\' else \'Paper\'} \\u00b7 week") if w\n          else ("Worst session", "\\u2014", TXT_DIM, ""))\n    ml, mp = data.book("month", "LIVE"), data.book("month", "PAPER")\n    if mp.sessions and ml.sessions:\n        c3 = ("Positive days", f"P {mp.positive_sessions}/{mp.sessions}", TXT_PRIMARY,\n              f"L {ml.positive_sessions}/{ml.sessions} \\u00b7 month")\n    elif mp.sessions or ml.sessions:\n        x, tag = (mp, "P") if mp.sessions else (ml, "L")\n        c3 = ("Positive days", f"{tag} {x.positive_sessions}/{x.sessions}", TXT_PRIMARY,\n              "days traded \\u00b7 month")\n    else:\n        c3 = ("Positive days", "\\u2014", TXT_DIM, "")\n    if ml.traded or mp.traded:\n        c4 = ("Charges", f"{CURRENCY}{round(ml.charges + mp.charges):,}", TXT_PRIMARY,\n              f"{bk(\'LIVE\')} {CURRENCY}{round(ml.charges):,} \\u00b7 {bk(\'PAPER\')} {CURRENCY}{round(mp.charges):,}")\n    else:\n        c4 = ("Charges", "\\u2014", TXT_DIM, "")\n    return [c1, c2, c3, c4]\n\n\n# ════════════════════════════════════════════════════════════════════\n#  FIXTURES  (synthetic; used by the suite and preview_expiry_card.py)\n# ════════════════════════════════════════════════════════════════════\n\ndef fixture_expiry_data(kind: str = "fleet") -> ExpiryCardData:\n    """\n    kind = "empty"  → nothing closed in the month window\n           "live"   → a single live strategy, paper idle\n           "fleet"  → the mockup\'s numbers (2 live + 12 paper strategies)\n    """\n    d = ExpiryCardData(date_str="29 Sep 2026",\n                       subtitle="Tue 29 Sep 2026 \\u00b7 15:40 IST \\u00b7 weekly expiry",\n                       week_range="Wed 23 \\u2013 Tue 29 Sep \\u00b7 5 sessions",\n                       month_range="since Sat 29 Aug \\u00b7 by expiry week")\n    wk_keys = [("2026-09-23", "Wed"), ("2026-09-24", "Thu"), ("2026-09-25", "Fri"),\n               ("2026-09-28", "Mon"), ("2026-09-29", "Tue")]\n    mo_keys = [("2026-09-01", "1 Sep"), ("2026-09-08", "8 Sep"), ("2026-09-15", "15 Sep"),\n               ("2026-09-22", "22 Sep"), ("2026-09-29", "29 Sep")]\n\n    def cells(keys, nets, counts):\n        return [Cell(k, lab, None if c == 0 else float(n), c)\n                for (k, lab), n, c in zip(keys, nets, counts)]\n\n    if kind == "empty":\n        d.week = {b: PeriodBook(cells=cells(wk_keys, [0] * 5, [0] * 5)) for b in BOOKS}\n        d.month = {b: PeriodBook(cells=cells(mo_keys, [0] * 5, [0] * 5)) for b in BOOKS}\n        return d\n\n    live_w = PeriodBook(net=965, trades=4, wins=2, charges=372,\n                        cells=cells(wk_keys, [0, -1240, 2860, 0, -655], [0, 1, 2, 0, 1]),\n                        sessions=3, positive_sessions=1)\n    live_m = PeriodBook(net=-1395, trades=19, wins=9, charges=1860,\n                        cells=cells(mo_keys, [1850, -6300, 4100, -2010, 965], [3, 5, 4, 3, 4]),\n                        sessions=17, positive_sessions=8)\n    if kind == "live":\n        d.week = {"LIVE": live_w, "PAPER": PeriodBook(cells=cells(wk_keys, [0] * 5, [0] * 5))}\n        d.month = {"LIVE": live_m, "PAPER": PeriodBook(cells=cells(mo_keys, [0] * 5, [0] * 5))}\n        d.rows = [StrategyPeriodRow("Tigris", "LIVE", 1620, 3, 2015, 12),\n                  StrategyPeriodRow("Outrider", "LIVE", -655, 1, -3410, 7)]\n        return d\n\n    paper_w = PeriodBook(net=45612, trades=103, wins=45, charges=9640,\n                         cells=cells(wk_keys, [9400, -8220, 18150, -7423, 33705], [21, 19, 24, 17, 22]),\n                         sessions=5, positive_sessions=3)\n    paper_m = PeriodBook(net=130250, trades=395, wins=178, charges=39440,\n                         cells=cells(mo_keys, [14300, -28700, 61200, 37838, 45612], [61, 78, 84, 69, 103]),\n                         sessions=20, positive_sessions=12)\n    d.week = {"LIVE": live_w, "PAPER": paper_w}\n    d.month = {"LIVE": live_m, "PAPER": paper_m}\n    d.rows = [\n        StrategyPeriodRow("Tigris", "LIVE", 1620, 3, 2015, 12),\n        StrategyPeriodRow("Outrider", "LIVE", -655, 1, -3410, 7),\n        StrategyPeriodRow("Velvet", "PAPER", 64562, 1, 71300, 4),\n        StrategyPeriodRow("Timberwolf", "PAPER", -12480, 2, 38900, 6),\n        StrategyPeriodRow("Baobab", "PAPER", -18300, 12, -32150, 41),\n        StrategyPeriodRow("Icarus", "PAPER", 14200, 16, 29400, 58),\n        StrategyPeriodRow("Scenic", "PAPER", -9600, 22, 18750, 88, approx=True),\n        StrategyPeriodRow("Tigris", "PAPER", 3900, 5, 12300, 19),\n        StrategyPeriodRow("Scala", "PAPER", -6100, 18, -9800, 70),\n        StrategyPeriodRow("Scribe", "PAPER", 5802, 11, 8100, 44),\n        StrategyPeriodRow("Indica", "PAPER", 2100, 13, -4600, 47),\n        StrategyPeriodRow("Harbor", "PAPER", 0, 0, -2900, 9),\n        StrategyPeriodRow("Breaker", "PAPER", 1900, 2, 2180, 5),\n        StrategyPeriodRow("Bobbin", "PAPER", -372, 1, -1230, 4),\n    ]\n    return d\n\n\nif __name__ == "__main__":\n    png = build_expiry_card_png(fixture_expiry_data("fleet"))\n    assert png, "render returned None"\n    with open("/tmp/expiry_card_demo.png", "wb") as f:\n        f.write(png)\n    print(f"OK \\u2014 wrote {len(png):,} bytes to /tmp/expiry_card_demo.png")\n'
DATA_SRC    = '"""\nEXPIRY CARD DATA SOURCE — week + month buckets from the dashboard\'s legs read.\n\napp/api/telegram_expiry_data.py          ── EXPIRY_CARD_20260929 ──\n\nbuild_expiry_card_data() assembles the ExpiryCardData the renderer consumes:\n\n  windows   day0 = 00:00 IST today; week = fleet_today_routes._week_from(day0)\n            (7 calendar days ending today); month = _month_from(day0) (same\n            calendar day last month). Identical to the Modern dashboard\'s\n            Week P/L / Month P/L, so the card and the ledger agree.\n  legs      fleet_today_routes._legs_for(sid) for every FLEET_IDS strategy —\n            the same read the dashboard makes (paper_trades + trades + the\n            V3/V5/TMA/VET mappers; ROW_LIMIT newest per store). Closed legs\n            whose EXIT falls in the window count; net = gross − charges.\n  counts    positions, not legs: _positions() (TSG baskets cluster) and\n            _baskets() for wins, exactly as the dashboard\'s closed_trades.\n  cells     week strip = one cell per NSE session (is_trading_day) in the\n            window; month strip = one cell per expiry week, keyed by\n            expected_expiry_for_day(exit day) so a Monday session before a\n            Tuesday holiday lands in the same cell as its Tuesday.\n  approx    a (strategy, book) is ≈ when its legs read hit ROW_LIMIT inside\n            the window or any leg\'s charges are modelled — the dashboard\'s\n            rule; it propagates to the row and the book total.\n\nRead-only. Every strategy is wrapped so one failing read drops that strategy\nand records a warning instead of blanking the card.\n"""\n\nfrom __future__ import annotations\n\nimport time\nfrom datetime import date, datetime, timedelta\nfrom typing import Dict, List, Optional\n\nfrom app.event_bus.audit_logger import write_audit_log\nfrom app.config.strategy_display import codename   # ── UI_MASK ── codenames on the PNG\nfrom app.api.telegram_expiry_card import (\n    ExpiryCardData, PeriodBook, StrategyPeriodRow, Cell, BOOKS,\n)\n\nIST_OFF = 5 * 3600 + 30 * 60\n\n\n# ───────────────────────── seams (monkeypatched by the suite) ────────────\n\ndef _fl():\n    from app.api import fleet_today_routes as f\n    return f\n\n\ndef _cr():\n    from app.api import closed_recent_routes as c\n    return c\n\n\ndef _expected_expiry(d: date) -> date:\n    from app.backtest.engine.expiry_calendar import expected_expiry_for_day\n    return expected_expiry_for_day(d)\n\n\ndef _is_trading_day(d: date) -> bool:\n    try:\n        from app.utils.market_hours import is_trading_day\n        return bool(is_trading_day(d))\n    except Exception:\n        return d.weekday() < 5\n\n\n# ───────────────────────── calendar helpers ──────────────────────────────\n\ndef _ist_date(ts: int) -> date:\n    g = time.gmtime(int(ts) + IST_OFF)\n    return date(g.tm_year, g.tm_mon, g.tm_mday)\n\n\ndef _sessions(from_ts: int, to_ts: int) -> List[date]:\n    """NSE sessions (IST dates) from `from_ts` to `to_ts`, inclusive."""\n    d, end = _ist_date(from_ts), _ist_date(to_ts)\n    out = []\n    while d <= end:\n        if _is_trading_day(d):\n            out.append(d)\n        d += timedelta(days=1)\n    return out\n\n\ndef _day_label(d: date) -> str:\n    return d.strftime("%a")\n\n\ndef _expiry_label(e: date) -> str:\n    return f"{e.day} {e:%b}"\n\n\ndef _week_template(sessions: List[date]) -> List[Cell]:\n    return [Cell(d.isoformat(), _day_label(d)) for d in sessions]\n\n\ndef _month_template(sessions: List[date]) -> List[Cell]:\n    seen: Dict[str, Cell] = {}\n    for d in sessions:\n        e = _expected_expiry(d)\n        seen.setdefault(e.isoformat(), Cell(e.isoformat(), _expiry_label(e)))\n    return list(seen.values())\n\n\ndef _week_range(sessions: List[date]) -> str:\n    if not sessions:\n        return "no sessions in window"\n    a, b = sessions[0], sessions[-1]\n    left = f"{a:%a} {a.day}" + ("" if a.month == b.month else f" {a:%b}")\n    return f"{left} \\u2013 {b:%a} {b.day} {b:%b} \\u00b7 {len(sessions)} session{\'s\' if len(sessions) != 1 else \'\'}"\n\n\ndef _month_range(month_from: int) -> str:\n    d = _ist_date(month_from)\n    return f"since {d:%a} {d.day} {d:%b} \\u00b7 by expiry week"\n\n\n# ───────────────────────── aggregation ───────────────────────────────────\n\ndef _groups(fl, sid: str, legs: List[dict]) -> List[List[dict]]:\n    """Positions: TSG legs cluster into baskets; everything else is one leg."""\n    if not legs:\n        return []\n    if sid in fl.BASKET_STRATEGIES:\n        return _cr()._baskets(legs)\n    return [[l] for l in legs]\n\n\ndef _net(l: dict) -> float:\n    return float(l["gross"]) - float(l["charges"])\n\n\ndef _cell_of(cells: List[Cell], key: str, label: str) -> Cell:\n    for c in cells:\n        if c.key == key:\n            return c\n    c = Cell(key, label)          # exit on a day outside the session template\n    cells.append(c)\n    cells.sort(key=lambda x: x.key)\n    return c\n\n\ndef _add_to_cell(c: Cell, net: float, n: int) -> None:\n    c.net = (c.net or 0.0) + net\n    c.trades += n\n\n\ndef build_expiry_card_data(now: Optional[int] = None, *, expiry: bool = True) -> ExpiryCardData:\n    fl, cr = _fl(), _cr()\n    now = int(now or time.time())\n    day0 = cr._day_start(now)\n    week_from = fl._week_from(day0)\n    month_from = fl._month_from(day0)\n    warns: list = []\n\n    wk_sessions = _sessions(week_from, now)\n    mo_sessions = _sessions(month_from, now)\n    wk_tpl = _week_template(wk_sessions)\n    mo_tpl = _month_template(mo_sessions)\n\n    week = {b: PeriodBook(cells=[Cell(c.key, c.label) for c in wk_tpl]) for b in BOOKS}\n    month = {b: PeriodBook(cells=[Cell(c.key, c.label) for c in mo_tpl]) for b in BOOKS}\n    day_net: Dict[str, Dict[str, float]] = {b: {} for b in BOOKS}   # month: day key -> net\n    rows: List[StrategyPeriodRow] = []\n\n    for sid in fl.FLEET_IDS:\n        try:\n            legs = fl._legs_for(sid, warns)\n        except Exception as e:\n            warns.append(f"{sid}: {e!r}")\n            continue\n        for book in BOOKS:\n            book_legs = [l for l in legs if l["book"] == book]\n            mine = [l for l in book_legs\n                    if not l["open"] and l["exit_ts"] and month_from <= int(l["exit_ts"]) <= now]\n            if not mine:\n                continue\n            truncated = (len(book_legs) >= cr.ROW_LIMIT\n                         and any(int(l["entry_ts"] or 0) >= month_from for l in book_legs[-1:]))\n            approx = truncated or any(l["approx"] for l in mine)\n            wk = [l for l in mine if int(l["exit_ts"]) >= week_from]\n\n            g_m, g_w = _groups(fl, sid, mine), _groups(fl, sid, wk)\n            net_m = sum(_net(l) for l in mine)\n            net_w = sum(_net(l) for l in wk)\n            rows.append(StrategyPeriodRow(codename(sid), book, round(net_w, 2), len(g_w),\n                                          round(net_m, 2), len(g_m), approx))\n\n            for period, groups, pb in (("month", g_m, month[book]), ("week", g_w, week[book])):\n                for grp in groups:\n                    gnet = sum(_net(l) for l in grp)\n                    pb.net += gnet\n                    pb.trades += 1\n                    pb.wins += 1 if gnet >= 0 else 0\n                    pb.charges += sum(float(l["charges"]) for l in grp)\n                    exit_ts = max(int(l["exit_ts"]) for l in grp)\n                    d = _ist_date(exit_ts)\n                    if period == "week":\n                        _add_to_cell(_cell_of(pb.cells, d.isoformat(), _day_label(d)), gnet, 1)\n                    else:\n                        e = _expected_expiry(d)\n                        _add_to_cell(_cell_of(pb.cells, e.isoformat(), _expiry_label(e)), gnet, 1)\n                        day_net[book][d.isoformat()] = day_net[book].get(d.isoformat(), 0.0) + gnet\n                pb.approx = pb.approx or approx\n\n    # keep the two books\' strips aligned: a cell appended for one book (an\n    # exit on a day outside the session template) exists, empty, for the other\n    for period in (week, month):\n        keys = {c.key: c.label for b in BOOKS for c in period[b].cells}\n        for b in BOOKS:\n            have = {c.key for c in period[b].cells}\n            period[b].cells.extend(Cell(k, lab) for k, lab in keys.items() if k not in have)\n            period[b].cells.sort(key=lambda c: c.key)\n\n    for b in BOOKS:\n        for pb in (week[b], month[b]):\n            pb.net = round(pb.net, 2)\n            pb.charges = round(pb.charges, 2)\n        month[b].sessions = len(day_net[b])\n        month[b].positive_sessions = sum(1 for v in day_net[b].values() if v > 0)\n\n    # Live first, then |month net| descending — the daily card\'s tile order\n    rows.sort(key=lambda r: (0 if r.mode == "LIVE" else 1, -abs(r.month_net)))\n\n    for w in warns:\n        write_audit_log(f"[EXPIRY_CARD][WARN] {w}")\n\n    n = datetime.fromtimestamp(now)\n    return ExpiryCardData(\n        date_str=n.strftime("%d %b %Y"),\n        subtitle=(n.strftime("%a %d %b %Y") + " \\u00b7 " + n.strftime("%H:%M") + " IST \\u00b7 "\n                  + ("weekly expiry" if expiry else "not an expiry day (manual)")),\n        week_range=_week_range(wk_sessions),\n        month_range=_month_range(month_from),\n        week=week, month=month, rows=rows, warnings=list(warns),\n    )\n'
SEND_SRC    = '"""\nEXPIRY CARD SENDER — expiry-day gate, caption, sendPhoto + text fallback.\n\napp/api/telegram_expiry_send.py          ── EXPIRY_CARD_20260929 ──\n\nContract (per channel):\n  1. ExpiryCardData is built ONCE by the scheduler (build_expiry_card_data_once)\n     and passed to every channel.\n  2. Render PNG. If render returns None -> send the text fallback (the same\n     four period nets as a message) so the summary is never lost.\n  3. sendPhoto with a caption carrying the four nets (Live · Paper for the\n     week and for the month — never summed). If sendPhoto fails -> text\n     fallback.\n  4. If the data could not be built at all -> a one-line notice, so the\n     absence of a card is visible rather than silent.\n\nExpiry-day gate: is_expiry_day(day) is live_dte(day) == 0 — the same\nresolver dte_lot_mult uses at the 09:15 day roll, so a Tuesday holiday\'s\nMonday expiry is handled without special casing. None (calendar failure)\ntells the scheduler to skip and log.\n"""\n\nfrom __future__ import annotations\n\nfrom datetime import date\nfrom typing import Optional\n\nfrom app.event_bus.audit_logger import write_audit_log\nfrom app.api.telegram_api import send_telegram_message\nfrom app.api.telegram_summary_send import _send_photo\nfrom app.api.telegram_summary_card import _fmt_signed_rs\nfrom app.api.telegram_expiry_card import ExpiryCardData, build_expiry_card_png\nfrom app.api.telegram_expiry_data import build_expiry_card_data\n\n\ndef is_expiry_day(day: date) -> Optional[bool]:\n    """True on the session the weekly contract expires (0 DTE), False otherwise,\n    None if the calendar cannot be evaluated."""\n    try:\n        from app.engine.dte_live import live_dte\n        dte = live_dte(day)\n        return None if dte is None else (dte == 0)\n    except Exception as e:\n        write_audit_log(f"[EXPIRY_CARD] expiry-day check failed: {e!r}")\n        return None\n\n\ndef build_expiry_card_data_once(now: Optional[int] = None, *, expiry: bool = True) -> Optional[ExpiryCardData]:\n    try:\n        return build_expiry_card_data(now, expiry=expiry)\n    except Exception as e:\n        write_audit_log(f"[EXPIRY_CARD] build_expiry_card_data failed: {e!r}")\n        return None\n\n\ndef _books_line(data: ExpiryCardData, period: str) -> str:\n    def one(label, book):\n        pb = data.book(period, book)\n        return f"{label} {_fmt_signed_rs(pb.net)}" if pb.traded else f"{label} no trades"\n    return one("Live", "LIVE") + " \\u00b7 " + one("Paper", "PAPER")\n\n\ndef expiry_caption(data: ExpiryCardData) -> str:\n    """HTML caption for sendPhoto — shows in the notification preview."""\n    return (f"\\U0001F4C5 <b>Expiry summary</b> \\u00b7 {data.date_str}\\n"\n            f"Week: <b>{_books_line(data, \'week\')}</b>\\n"\n            f"Month: <b>{_books_line(data, \'month\')}</b>")\n\n\ndef expiry_text(data: ExpiryCardData) -> str:\n    """Text fallback when the card cannot be rendered or sent."""\n    return expiry_caption(data) + "\\n<i>(card unavailable \\u2014 text fallback)</i>"\n\n\ndef send_expiry_summary_card(*, bot_token: str, chat_id: str,\n                             data: Optional[ExpiryCardData]) -> bool:\n    """Card-first, text fallback. Returns True only when sendPhoto succeeded."""\n    if not bot_token or not chat_id:\n        write_audit_log("[EXPIRY_CARD] missing bot_token/chat_id \\u2014 skipping channel")\n        return False\n    if data is None:\n        send_telegram_message(bot_token, chat_id,\n                              "\\U0001F4C5 <b>Expiry summary</b> could not be built \\u2014 see the audit log.")\n        return False\n\n    png = build_expiry_card_png(data)\n    if not png:\n        write_audit_log("[EXPIRY_CARD] render returned None \\u2014 text fallback")\n        send_telegram_message(bot_token, chat_id, expiry_text(data))\n        return False\n\n    if _send_photo(bot_token, chat_id, png, expiry_caption(data)):\n        write_audit_log(f"[EXPIRY_CARD] expiry summary card sent -> {chat_id}")\n        return True\n    write_audit_log("[EXPIRY_CARD] sendPhoto failed \\u2014 text fallback")\n    send_telegram_message(bot_token, chat_id, expiry_text(data))\n    return False\n'
PREVIEW_SRC = '#!/usr/bin/env python3\n"""\nLOCAL EXPIRY CARD PREVIEW — render the week + month expiry card from the REAL\ndatabase (or a synthetic fixture) and save it to a PNG. Sends nothing.\n\n    cd backend\n    python app/tests/preview_expiry_card.py                    # real DB, today\'s windows\n    python app/tests/preview_expiry_card.py --out ~/Desktop/expiry.png\n    python app/tests/preview_expiry_card.py --fixture fleet    # the mockup\'s numbers\n    python app/tests/preview_expiry_card.py --fixture empty\n    python app/tests/preview_expiry_card.py --fixture live\n\n── EXPIRY_CARD_20260929 ── same data source + renderer the scheduler uses at\n15:40 on expiry days, so this is exactly the card that will be sent. The real\nDB path works on any day (the subtitle says "not an expiry day (manual)").\n"""\n\nimport argparse\nimport os\nimport sys\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--out", default=os.path.join(os.getcwd(), "expiry_card_preview.png"))\n    parser.add_argument("--fixture", choices=("empty", "live", "fleet"), default=None,\n                        help="Render a synthetic card instead of reading the real DB")\n    args = parser.parse_args()\n\n    try:\n        from app.api.telegram_expiry_card import build_expiry_card_png, fixture_expiry_data, BOOKS\n    except ModuleNotFoundError as e:\n        print(f"[PREVIEW] import failed: {e}")\n        print("[PREVIEW] Run from the backend root so `app.*` imports resolve (pip install matplotlib).")\n        sys.exit(1)\n\n    if args.fixture:\n        print(f"[PREVIEW] Building synthetic data: fixture={args.fixture}")\n        data = fixture_expiry_data(args.fixture)\n    else:\n        from app.api.telegram_expiry_data import build_expiry_card_data\n        from app.api.telegram_expiry_send import is_expiry_day\n        from datetime import date\n        exp = is_expiry_day(date.today())\n        print(f"[PREVIEW] Building from the real DB (today is {\'an expiry day\' if exp else \'not an expiry day\'})...")\n        data = build_expiry_card_data(expiry=bool(exp))\n\n    print(f"[PREVIEW] {data.subtitle}")\n    print(f"[PREVIEW] week : {data.week_range}")\n    print(f"[PREVIEW] month: {data.month_range}")\n    for period in ("week", "month"):\n        for b in BOOKS:\n            pb = data.book(period, b)\n            cells = " ".join(f"{c.label}:{\'—\' if c.net is None else f\'{c.net:+,.0f}\'}" for c in pb.cells)\n            print(f"[PREVIEW] {period:5} {b:5} net={pb.net:+,.0f} trades={pb.trades} wins={pb.wins}"\n                  f" charges={pb.charges:,.0f}{\' ≈\' if pb.approx else \'\'}  | {cells}")\n    print(f"[PREVIEW] rows: {len(data.rows)}")\n    for r in data.rows:\n        print(f"            {r.name:12} {r.mode:5} week={r.week_net:+,.0f} ({r.week_trades})"\n              f"  month={r.month_net:+,.0f} ({r.month_trades}){\' ≈\' if r.approx else \'\'}")\n    for w in data.warnings:\n        print(f"[PREVIEW] warn: {w}")\n\n    png = build_expiry_card_png(data)\n    if not png:\n        print("[PREVIEW] Render returned None (is matplotlib installed in this env?)")\n        sys.exit(2)\n    with open(args.out, "wb") as f:\n        f.write(png)\n    print(f"[PREVIEW] Saved: {args.out}  ({len(png):,} bytes)")\n    try:\n        if sys.platform == "darwin":\n            os.system(f\'open "{args.out}"\')\n        elif sys.platform.startswith("win"):\n            os.startfile(args.out)  # type: ignore[attr-defined]\n    except Exception:\n        pass\n\n\nif __name__ == "__main__":\n    main()\n'
TEST_SRC    = '# backend/app/tests/test_expiry_card.py\n#\n# ── EXPIRY_CARD_20260929 ── behavioural suite for the week + month expiry card:\n#   renderer   three fixtures render, fail-open, compact formatting\n#   data       buckets from synthetic legs on the REAL epoch clock through the\n#              dashboard\'s own window functions; baskets, approx, truncation,\n#              cells, positive days, one failing strategy does not blank the card\n#   sender     caption / fallback text, expiry-day gate, photo-fail -> text\n#   scheduler  fires once at 15:40 on an expiry day, never on other days,\n#              skips when the calendar is unavailable\n#\n#   cd backend && PYTHONPATH=$PWD python3 app/tests/test_expiry_card.py\n\nimport io\nimport struct\nimport sys\nimport time\nfrom datetime import date, datetime, timedelta, timezone\n\nimport app.api.telegram_expiry_card as C\nimport app.api.telegram_expiry_data as D\nimport app.api.telegram_expiry_send as S\nimport app.api.fleet_today_routes as F\nimport app.api.closed_recent_routes as CR\nimport app.services.telegram_scheduler as SCH\n\nFAILS = []\nIST = timezone(timedelta(hours=5, minutes=30))\n\n\ndef check(name, cond, detail=""):\n    print(f"  {\'PASS\' if cond else \'FAIL\'}  {name}" + (f"  [{detail}]" if detail and not cond else ""))\n    if not cond:\n        FAILS.append(name)\n\n\ndef hex_rgb(h):\n    h = h.lstrip("#")\n    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))\n\n\n# ───────────────────────────── renderer ─────────────────────────────\n\ndef test_renderer():\n    print("renderer:")\n    heights = {}\n    for kind in ("empty", "live", "fleet"):\n        png = C.build_expiry_card_png(C.fixture_expiry_data(kind))\n        check(f"{kind}: renders", bool(png))\n        if not png:\n            continue\n        check(f"{kind}: PNG signature", png[:8] == b"\\x89PNG\\r\\n\\x1a\\n")\n        w, h = struct.unpack(">II", png[16:24])\n        heights[kind] = h\n        check(f"{kind}: width \\u2248 {C.W_PX}px", abs(w - C.W_PX) <= 2, str(w))\n        try:\n            from PIL import Image\n            im = Image.open(io.BytesIO(png)).convert("RGB")\n            check(f"{kind}: Midnight background", im.getpixel((3, 3)) == hex_rgb(C.BG_CARD))\n            if kind != "empty":\n                colours = {c for _, c in (im.getcolors(1 << 22) or [])}\n                check(f"{kind}: profit/loss ink present", hex_rgb(C.UP) in colours or hex_rgb(C.DN) in colours)\n        except ImportError:\n            print("  skip  PIL not available")\n    check("height: empty < live < fleet", heights.get("empty", 0) < heights.get("live", 0) < heights.get("fleet", 0), str(heights))\n    check("fleet (14 rows) \\u2212 live (2 rows) = 12 table rows",\n          abs(heights.get("fleet", 0) - heights.get("live", 0) - 12 * C.ROW_H) <= 2, str(heights))\n\n    orig = C._render\n    C._render = lambda d: (_ for _ in ()).throw(RuntimeError("boom"))\n    try:\n        check("render error \\u2192 None (fail-open)", C.build_expiry_card_png(C.fixture_expiry_data("fleet")) is None)\n    finally:\n        C._render = orig\n\n    check("_fmt_k", (C._fmt_k(18150), C._fmt_k(-8220), C._fmt_k(655), C._fmt_k(-130250), C._fmt_k(0))\n          == ("+18.2k", "-8.2k", "+655", "-130k", "+0"))\n    d = C.fixture_expiry_data("fleet")\n    check("best session = Tue +33,705 Paper", d.best_session[0].net == 33705 and d.best_session[1] == "PAPER")\n    check("worst session = Thu \\u22128,220 Paper", d.worst_session[0].net == -8220 and d.worst_session[0].label == "Thu")\n    cells = C._footer_cells(d)\n    check("footer labels", [c[0] for c in cells] == ["Best session", "Worst session", "Positive days", "Charges"])\n    check("footer positive days P 12/20, L 8/17", cells[2][1] == "P 12/20" and cells[2][3].startswith("L 8/17"))\n    check("footer charges L/P split", cells[3][3] == "L \\u20b91,860 \\u00b7 P \\u20b939,440", cells[3][3])\n    e = C.fixture_expiry_data("empty")\n    check("empty: no trades anywhere, footer dashes", not e.any_trades and all(c[1] == "\\u2014" for c in C._footer_cells(e)))\n    # cells missing on one book still render (template borrowed from the other book)\n    d2 = C.fixture_expiry_data("live")\n    d2.week["PAPER"].cells = []\n    check("book without cells renders", bool(C.build_expiry_card_png(d2)))\n\n\n# ───────────────────────────── data layer ───────────────────────────\n\ndef _leg(book, entry_ts, exit_ts, gross, charges=50.0, approx=False, open_=False, short=True):\n    return {"id": f"{book}:{entry_ts}", "book": book, "symbol": "NIFTY", "short": short, "qty": 65,\n            "lots": 1, "entry": 100.0, "exit": 90.0, "entry_ts": int(entry_ts), "exit_ts": (None if open_ else int(exit_ts)),\n            "reason": "SL", "open": open_, "gross": float(gross), "charges": float(charges),\n            "net": float(gross) - float(charges), "approx": approx, "leg": None}\n\n\ndef test_data():\n    print("data (synthetic legs, real clock, dashboard windows):")\n    now = int(time.time())\n    day0 = CR._day_start(now)\n    week_from = F._week_from(day0)\n    month_from = F._month_from(day0)\n    H = 3600\n    D_ = 86400\n\n    legs = {\n        # VET_V1: paper — today (in week), 3 days ago (in week), 12 days ago (month only), 40 days ago (out)\n        "VET_V1": [\n            _leg("PAPER", now - 2 * H, now - H, 64562.0, 412.0),\n            _leg("PAPER", now - 3 * D_ - 2 * H, now - 3 * D_ - H, -1200.0, 90.0),\n            _leg("PAPER", now - 12 * D_ - 2 * H, now - 12 * D_ - H, 300.0, 80.0),\n            _leg("PAPER", now - 40 * D_ - 2 * H, now - 40 * D_ - H, 9999.0, 80.0),\n            _leg("PAPER", now - 600, None, 0.0, 0.0, open_=True),                     # open — ignored\n            _leg("LIVE", now - 5 * D_ - 2 * H, now - 5 * D_ - H, 700.0, 60.0),        # live, in week\n        ],\n        # TSG_V1: paper basket — two legs entered in the same minute 10 days ago = ONE position\n        "TSG_V1": [\n            _leg("PAPER", now - 10 * D_ - 4 * H, now - 10 * D_ - H, -3000.0, 100.0),\n            _leg("PAPER", now - 10 * D_ - 4 * H + 30, now - 10 * D_ - H, 500.0, 100.0),\n        ],\n        # ORB_V1: live, modelled charges (approx) 8 days ago\n        "ORB_V1": [_leg("LIVE", now - 8 * D_ - 2 * H, now - 8 * D_ - H, -655.0, 94.0, approx=True)],\n    }\n\n    saved = F._legs_for\n    F._legs_for = lambda sid, warns: legs.get(sid, [])\n    try:\n        data = D.build_expiry_card_data(now, expiry=True)\n    finally:\n        F._legs_for = saved\n\n    names = {(r.name, r.mode): r for r in data.rows}\n    v = names.get(("Velvet", "PAPER"))\n    check("Velvet paper row present (codenamed)", v is not None)\n    if v:\n        check("Velvet week: 2 positions, net 64,562\\u2212412 + (\\u22121,200\\u221290)", v.week_trades == 2 and abs(v.week_net - (64150.0 - 1290.0)) < 1e-6, f"{v.week_trades} {v.week_net}")\n        check("Velvet month: 3 positions (40-day-old leg excluded, open leg excluded)", v.month_trades == 3 and abs(v.month_net - (64150.0 - 1290.0 + 220.0)) < 1e-6, f"{v.month_trades} {v.month_net}")\n        check("Velvet not approx", not v.approx)\n    vl = names.get(("Velvet", "LIVE"))\n    check("Velvet live row separate from paper", vl is not None and vl.week_trades == 1 and vl.month_net == 640.0)\n    t = names.get(("Tigris", "PAPER"))\n    check("TSG basket counted as ONE position, net \\u22122,700", t is not None and t.month_trades == 1 and t.month_net == -2700.0 and t.week_trades == 0, str(t))\n    o = names.get(("Outrider", "LIVE"))\n    check("ORB live row approx (modelled charges)", o is not None and o.approx and o.month_net == -749.0)\n    check("rows: Live first, then |month| desc",\n          [r.mode for r in data.rows][:2] == ["LIVE", "LIVE"]\n          and [r.name for r in data.rows if r.mode == "PAPER"] == ["Velvet", "Tigris"], str([(r.name, r.mode) for r in data.rows]))\n\n    wp, wl = data.book("week", "PAPER"), data.book("week", "LIVE")\n    mp, ml = data.book("month", "PAPER"), data.book("month", "LIVE")\n    check("week PAPER totals", wp.trades == 2 and wp.wins == 1 and abs(wp.net - 62860.0) < 1e-6 and abs(wp.charges - 502.0) < 1e-6, f"{wp}")\n    check("week LIVE totals", wl.trades == 1 and wl.wins == 1 and wl.net == 640.0)\n    check("month PAPER totals (Velvet 3 + TSG basket 1)", mp.trades == 4 and mp.wins == 2 and abs(mp.net - (63080.0 - 2700.0)) < 1e-6, f"{mp.net} {mp.trades} {mp.wins}")\n    check("month LIVE totals (Velvet + Outrider)", ml.trades == 2 and abs(ml.net - (640.0 - 749.0)) < 1e-6 and ml.approx)\n    check("month PAPER positive days 2 of 3 (today +, 3d ago \\u2212, 12d ago +, TSG 10d ago \\u2212 => 4 days, 2 positive)",\n          mp.sessions == 4 and mp.positive_sessions == 2, f"{mp.sessions}/{mp.positive_sessions}")\n    check("week strip: today\'s cell carries +64,150 for PAPER",\n          any(c.key == D._ist_date(now - H).isoformat() and c.net == 64150.0 and c.trades == 1 for c in wp.cells), str([(c.key, c.net) for c in wp.cells]))\n    check("week strip: sessions in window only (\\u2264 7 cells), all keys within window",\n          0 < len(wp.cells) <= 7 and all(c.key >= D._ist_date(week_from).isoformat() for c in wp.cells))\n    exp_key = D._expected_expiry(D._ist_date(now - 12 * D_ - H)).isoformat()\n    check("month strip: 12-day-old leg lands in its expected-expiry cell",\n          any(c.key == exp_key and c.trades >= 1 for c in mp.cells), str([(c.key, c.net) for c in mp.cells]))\n    check("month strip keys are Tuesdays (expected expiry era)",\n          all(date.fromisoformat(c.key).weekday() == 1 for c in mp.cells), str([c.key for c in mp.cells]))\n    check("templates: both books share the same cell keys",\n          [c.key for c in wp.cells] == [c.key for c in wl.cells] and [c.key for c in mp.cells] == [c.key for c in ml.cells])\n    check("subtitle ends with \'weekly expiry\'", data.subtitle.endswith("IST \\u00b7 weekly expiry"), data.subtitle)\n    check("week_range mentions session count", "session" in data.week_range, data.week_range)\n    check("month_range \'since <day> \\u00b7 by expiry week\'", data.month_range.startswith("since ") and data.month_range.endswith("by expiry week"), data.month_range)\n    check("no warnings", data.warnings == [], str(data.warnings))\n    check("renders", bool(C.build_expiry_card_png(data)))\n\n    # truncation => approx: ROW_LIMIT legs for one (sid, book), oldest entered inside the window\n    many = [_leg("PAPER", now - 2 * D_ - 4 * H - i, now - 2 * D_ - H, 10.0, 1.0) for i in range(CR.ROW_LIMIT)]\n    F._legs_for = lambda sid, warns: many if sid == "IC_V2" else []\n    try:\n        d2 = D.build_expiry_card_data(now)\n    finally:\n        F._legs_for = saved\n    r = next(r for r in d2.rows if r.name == "Icarus")\n    check("legs read at ROW_LIMIT inside the window \\u2192 approx", r.approx and d2.book("month", "PAPER").approx)\n\n    # one strategy\'s read raising does not blank the card\n    def boom(sid, warns):\n        if sid == "IC_V2":\n            raise RuntimeError("db locked")\n        return legs.get(sid, [])\n    F._legs_for = boom\n    try:\n        d3 = D.build_expiry_card_data(now)\n    finally:\n        F._legs_for = saved\n    check("one failing strategy \\u2192 warning, other rows intact", len(d3.rows) == len(data.rows) and any("IC_V2" in w for w in d3.warnings), str(d3.warnings))\n\n    # manual (non-expiry) subtitle\n    F._legs_for = lambda sid, warns: []\n    try:\n        d4 = D.build_expiry_card_data(now, expiry=False)\n    finally:\n        F._legs_for = saved\n    check("manual run subtitle", d4.subtitle.endswith("not an expiry day (manual)") and d4.rows == [] and not d4.any_trades)\n    check("empty real-window card renders", bool(C.build_expiry_card_png(d4)))\n\n\n# ───────────────────────────── sender ───────────────────────────────\n\ndef test_sender():\n    print("sender:")\n    d = C.fixture_expiry_data("fleet")\n    cap = S.expiry_caption(d)\n    check("caption: week line", "Week: <b>Live +\\u20b9965 \\u00b7 Paper +\\u20b945,612</b>" in cap, cap)\n    check("caption: month line", "Month: <b>Live -\\u20b91,395 \\u00b7 Paper +\\u20b9130,250</b>" in cap, cap)\n    check("caption never sums the books", "Combined" not in cap and "Total" not in cap)\n    lv = C.fixture_expiry_data("live")\n    check("idle book reads \'no trades\'", "Paper no trades" in S.expiry_caption(lv))\n    check("text fallback = caption + note", S.expiry_text(d).startswith(cap) and "fallback" in S.expiry_text(d))\n\n    import app.engine.dte_live as DL\n    saved = DL.live_dte\n    try:\n        DL.live_dte = lambda day: 0\n        check("live_dte 0 \\u2192 expiry day", S.is_expiry_day(date(2026, 9, 29)) is True)\n        DL.live_dte = lambda day: 3\n        check("live_dte 3 \\u2192 not expiry day", S.is_expiry_day(date(2026, 9, 25)) is False)\n        DL.live_dte = lambda day: None\n        check("live_dte None \\u2192 None (calendar unavailable)", S.is_expiry_day(date(2026, 9, 25)) is None)\n        DL.live_dte = lambda day: (_ for _ in ()).throw(RuntimeError("x"))\n        check("live_dte raising \\u2192 None", S.is_expiry_day(date(2026, 9, 25)) is None)\n    finally:\n        DL.live_dte = saved\n    # real calendar: 29 Sep 2026 is a Tuesday expiry, 28 Sep a Monday 1DTE\n    check("real calendar: Tue 29 Sep 2026 is expiry day", S.is_expiry_day(date(2026, 9, 29)) is True)\n    check("real calendar: Mon 28 Sep 2026 is not", S.is_expiry_day(date(2026, 9, 28)) is False)\n\n    sent = []\n    msgs = []\n    sp, sm = S._send_photo, S.send_telegram_message\n    S._send_photo = lambda tok, chat, png, caption: (sent.append((chat, len(png), caption)) or True)\n    S.send_telegram_message = lambda tok, chat, msg, parse_mode="HTML": (msgs.append((chat, msg)) or True)\n    try:\n        ok = S.send_expiry_summary_card(bot_token="t", chat_id="c1", data=d)\n        check("photo path: sendPhoto called once with caption, no text", ok and len(sent) == 1 and sent[0][2] == cap and msgs == [])\n        sent.clear()\n        S._send_photo = lambda tok, chat, png, caption: False\n        ok = S.send_expiry_summary_card(bot_token="t", chat_id="c2", data=d)\n        check("sendPhoto fails \\u2192 text fallback to the same chat", not ok and msgs and msgs[-1][0] == "c2" and "fallback" in msgs[-1][1])\n        msgs.clear()\n        ok = S.send_expiry_summary_card(bot_token="t", chat_id="c3", data=None)\n        check("data None \\u2192 one-line notice", not ok and msgs and "could not be built" in msgs[-1][1])\n        msgs.clear()\n        orig = C._render\n        C._render = lambda dd: (_ for _ in ()).throw(RuntimeError("boom"))\n        try:\n            ok = S.send_expiry_summary_card(bot_token="t", chat_id="c4", data=d)\n        finally:\n            C._render = orig\n        check("render None \\u2192 text fallback", not ok and msgs and msgs[-1][0] == "c4")\n        check("missing chat_id \\u2192 False, nothing sent", S.send_expiry_summary_card(bot_token="t", chat_id="", data=d) is False)\n    finally:\n        S._send_photo, S.send_telegram_message = sp, sm\n\n\n# ───────────────────────────── scheduler ────────────────────────────\n\ndef test_scheduler():\n    print("scheduler gate:")\n    sch = SCH.TelegramScheduler()\n    calls = []\n    saved = (SCH.is_expiry_day, SCH._iter_active_channels, SCH.send_expiry_summary_card, SCH.build_expiry_card_data_once)\n    SCH._iter_active_channels = lambda key, **kw: [("tok", "chat1", {}), ("tok", "chat2", {})]\n    SCH.send_expiry_summary_card = lambda **kw: calls.append(kw) or True\n    SCH.build_expiry_card_data_once = lambda **kw: C.fixture_expiry_data("fleet")\n    try:\n        at = datetime(2026, 9, 29, sch.SUMMARY_HOUR, sch.SUMMARY_MINUTE, 5, tzinfo=IST)\n        SCH.is_expiry_day = lambda day: True\n        sch._handle_expiry_summary(at.replace(hour=10))\n        check("not the summary minute \\u2192 nothing", calls == [])\n        sch._handle_expiry_summary(at)\n        check("15:40 on an expiry day \\u2192 one send per channel", len(calls) == 2 and {c["chat_id"] for c in calls} == {"chat1", "chat2"})\n        sch._handle_expiry_summary(at.replace(second=35))\n        check("same day, next tick \\u2192 not again", len(calls) == 2)\n        check("data built once and shared", calls[0]["data"] is calls[1]["data"])\n\n        sch2 = SCH.TelegramScheduler()\n        SCH.is_expiry_day = lambda day: False\n        sch2._handle_expiry_summary(at)\n        check("non-expiry day \\u2192 nothing, day marked", len(calls) == 2 and sch2._last_expiry_date == "2026-09-29")\n\n        sch3 = SCH.TelegramScheduler()\n        SCH.is_expiry_day = lambda day: None\n        sch3._handle_expiry_summary(at)\n        check("calendar unavailable \\u2192 skipped, day marked", len(calls) == 2 and sch3._last_expiry_date == "2026-09-29")\n\n        sch4 = SCH.TelegramScheduler()\n        SCH.is_expiry_day = lambda day: False\n        sch4.run_expiry_summary_now()\n        check("manual trigger sends on a non-expiry day too", len(calls) == 4)\n        check("scheduler tick order: daily then expiry", "self._handle_daily_summary(now)" in open(SCH.__file__, encoding="utf-8").read().split("self._handle_expiry_summary(now)")[0])\n    finally:\n        SCH.is_expiry_day, SCH._iter_active_channels, SCH.send_expiry_summary_card, SCH.build_expiry_card_data_once = saved\n\n\nif __name__ == "__main__":\n    test_renderer()\n    test_data()\n    test_sender()\n    test_scheduler()\n    print()\n    if FAILS:\n        print(f"FAILED ({len(FAILS)}):")\n        for f in FAILS:\n            print("  -", f)\n        sys.exit(1)\n    print("ALL PASS")\n'

