def apply_edits(src: str, edits, name: str) -> str:
    for old, new in edits:
        n = src.count(old)
        if n != 1:
            raise SystemExit(f"ABORT: {name} anchor not unique ({n} matches): {old[:70]!r}")
        src = src.replace(old, new)
    return src


