# working-copy drift guard (ORB_RECONCILE scar)
try:
    r = subprocess.run(["git", "status", "--porcelain", "--",
                        os.path.relpath(P_SCHED, ROOT), os.path.relpath(P_API, ROOT)],
                       cwd=ROOT, capture_output=True, text=True, timeout=20)
    if r.returncode != 0:
        raise FileNotFoundError("not a git repository")
    dirty = [l for l in r.stdout.splitlines() if l.strip()]
    if dirty and not ALLOW_DIRTY:
        die("git shows uncommitted changes on a target file:\n       " + "\n       ".join(dirty)
            + "\n       Commit or `git checkout` them first, or re-run with --allow-dirty.")
    print("git: targets clean" if not dirty else "git: targets dirty (--allow-dirty)")
except FileNotFoundError as e:
    print(f"git: {e} — drift guard skipped")

